# -*- coding: utf-8 -*-
import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from native import *
N = 'nl'
NR = [('/nl/instagram-account-uitgeschakeld/', 'Instagram-account uitgeschakeld'), ('/nl/dsa-recht-op-beroep-meta/', 'DSA: recht op beroep'), ('/nl/instagram-bezwaar-afgewezen/', 'Bezwaar afgewezen')]
page(N, 'zakelijk-instagram-account-uitgeschakeld-inkomsten', 'Zakelijk Instagram-account uitgeschakeld: zo bescherm je je omzet',
 'Je zakelijke Instagram-account is uitgeschakeld en de verkoop ligt stil. Wat je eerst doet, hoe je bezwaar maakt en hoe je klanten bereikbaar blijven.',
 'Zakelijk Instagram-account uitgeschakeld en het is je inkomen?', 'Zakelijk account uitgeschakeld',
 'Maak één keer goed bezwaar vanuit de melding, met juiste gegevens, voordat de termijn verloopt. Maak geen nieuwe accounts op dezelfde telefoon, want gekoppelde accounts worden vaak ook verwijderd. Laat klanten via e-mail, je website of Google Bedrijfsprofiel weten hoe ze je bereiken, en bewaar elke melding met de datum.',
 [('De eerste 48 uur', ol(['Maak een screenshot van de melding en de bezwaartermijn.', 'Maak bezwaar vanaf je gebruikelijke telefoon en leg kort uit wat je bedrijf verkoopt.', 'Doe de ID- of videoselfiecontrole één keer, met goed licht.', 'Controleer in Accountcentrum of je Facebook-profiel ook beperkt is.', 'Pauzeer advertenties die naar het account verwijzen.'])),
  ('Wat je beter niet doet', ul(['Geen nieuw zakelijk account met hetzelfde e-mailadres, nummer of toestel.', 'Niet betalen aan iemand in je DM die zegt iemand bij Meta te kennen.', 'Geen berichten massaal verwijderen.']))],
 [('Zijn mijn volgers weg?', 'Zolang het account is uitgeschakeld is het verborgen, niet verwijderd. Bij een geslaagd bezwaar komen volgers en berichten meestal terug.'),
  ('Kan ik in de tussentijd een nieuw account gebruiken?', 'Dat is riskant. Een nieuw account dat aan jou of je toestel is gekoppeld, kan om dezelfde reden worden verwijderd.'),
  ('Ik woon in de EU. Heb ik nog meer opties?', 'Ja. Na een afgewezen bezwaar kun je naar een geschilleninstantie zoals Appeals Centre Europe.')], NR)
page(N, 'back-up-instagram-account-ook-geblokkeerd', 'Back-up Instagram-account ook geblokkeerd: waarom en wat nu',
 'Je hoofdaccount is uitgeschakeld en daarna ging je back-up- of nieuwe account ook. Waarom gekoppelde accounts worden verwijderd en wat je beter doet.',
 'Je back-up Instagram-account is ook geblokkeerd?', 'Back-up ook geblokkeerd',
 'Instagram koppelt accounts via toestel, telefoonnummer, e-mail, betaalgegevens en Accountcentrum. Als één account wordt uitgeschakeld, gaat een gekoppeld back-up- of nieuw account vaak ook, soms omdat het wordt gezien als omzeilen van de beslissing. Stop met nieuwe accounts maken, maak bezwaar voor het hoofdaccount en bewaar bewijs dat het echt was.',
 [('Wat je nu doet', ol(['Maak geen nieuwe accounts meer.', 'Maak bezwaar voor het oorspronkelijke account, niet voor de back-up.', 'Bewaar screenshots van beide meldingen met datum.'])),
  ('Waarom het gebeurt', 'Meta noemt het omzeilen van handhaving als reden om ook gekoppelde accounts te verwijderen. Het gaat niet om wat je op het back-upaccount postte, maar om de koppeling.')],
 [('Kan ik bezwaar maken voor het back-upaccount?', 'Als er een bezwaarknop is, ja. Maar het hoofdaccount is meestal de sleutel.'),
  ('Helpt een ander toestel?', 'Een nieuw toestel om de beslissing te omzeilen gaat tegen de regels in.'),
  ('Komt het back-upaccount terug als het hoofdaccount terugkomt?', 'Niet automatisch, maar dan heeft het bezwaar voor de back-up meer kans.')], NR)
page(N, 'appeals-centre-europe-instagram-facebook', 'Appeals Centre Europe: beroep tegen een Instagram-ban',
 'Hoe Appeals Centre Europe werkt bij een opgeschort Instagram-, Facebook- of TikTok-account: wie het kan gebruiken, de termijn en wat je kunt verwachten.',
 'Kan Appeals Centre Europe je Instagram- of Facebook-ban beoordelen?', 'Appeals Centre Europe',
 'Appeals Centre Europe is een erkende geschilleninstantie onder de Europese DSA. Het beoordeelt accountopschortingen en contentbeslissingen van onder meer Facebook, Instagram, Threads, TikTok en YouTube. Je moet in de EU wonen, 16 jaar of ouder zijn en binnen zes maanden na de beslissing indienen. Gebruikers betalen op dit moment niets.',
 [('Zo dien je in', ol(['Rond eerst het bezwaar in de app af en bewaar de beslissing.', 'Ga naar appealscentre.eu en kies het platform.', 'Geef aan dat het om een accountopschorting gaat.', 'Voeg je gebruikersnaam, de datum en de referentie uit de melding toe.', 'Leg kort uit waarom de beslissing niet klopt. Nederlands is een van de talen.'])),
  ('Wat je kunt verwachten', 'Het oordeel is niet bindend, maar het platform moet te goeder trouw meewerken. Volgens eigen cijfers draait het centrum een deel van de opschortingen terug, niet allemaal.')],
 [('Kan ik dit vanuit België gebruiken?', 'Ja, België valt onder de EU.'),
  ('Werkt het voor een gehackt account?', 'Het kijkt naar de beslissing van het platform, zoals de ban na een hack. Het herstel zelf gaat via het platform.'),
  ('Kan Unbanz dit voor me indienen?', 'Je dient het zelf in. We helpen je de feiten op een rij te zetten.')], [NR[1], NR[2], ('/nl/instagram-account-opgeschort-180-dagen/', 'Opgeschort, 180 dagen')])
page(N, 'meta-verified-ondersteuning-uitgeschakeld-account', 'Meta Verified-ondersteuning bij een uitgeschakeld account',
 'Wat Meta Verified-ondersteuning wel en niet kan als je Instagram- of Facebook-account is uitgeschakeld of gehackt, en hoe je de chat opent.',
 'Helpt Meta Verified-ondersteuning bij een uitgeschakeld account?', 'Meta Verified-ondersteuning',
 'Meta Verified geeft toegang tot chat- of e-mailondersteuning, maar alleen vanaf een actief account met een abonnement. Is het account zelf uitgeschakeld, dan kan de ondersteuning vaak alleen naar het gewone bezwaar verwijzen. Een gekoppeld actief account met Meta Verified kan soms helpen bij hackproblemen.',
 [('Zo open je de ondersteuning', ol(['Open het account met Meta Verified.', 'Ga naar Accountcentrum, Meta Verified en kies Contact opnemen.', 'Geef de gebruikersnaam van het getroffen account en de datum.'])),
  ('Wat je kunt verwachten', 'Medewerkers kunnen uitleggen, een melding doorzetten of naar het juiste formulier verwijzen. Ze kunnen een ban meestal niet zelf terugdraaien.')],
 [('Moet ik Meta Verified nemen om mijn account terug te krijgen?', 'Niet als het account al is uitgeschakeld. Maak eerst bezwaar.'),
  ('Kan ik opzeggen?', 'Ja, via Accountcentrum of de app store waar je het afsloot.'),
  ('Zijn er andere routes?', 'In de EU kun je na een afgewezen bezwaar naar Appeals Centre Europe.')], NR)
page(N, 'instagram-gehackt-crypto-berichten', 'Instagram gehackt en er staan crypto-berichten op je account',
 'Je Instagram-account is gehackt en plaatst crypto- of investeringsoplichting. Hoe je het herstelt, volgers waarschuwt en melding doet.',
 'Je gehackte Instagram plaatst crypto-oplichting?', 'Gehackt, crypto-berichten',
 'Als je gehackte Instagram-account crypto-oplichting plaatst, herstel eerst de toegang via instagram.com/hacked of de beveiligingsmail, en verwijder dan de berichten en verhalen. Waarschuw je volgers via een ander kanaal dat het niet om jou ging. Doe aangifte bij de politie en meld het bij de Fraudehelpdesk.',
 [('Stap voor stap', ol(['Gebruik de link in de echte beveiligingsmail of de hackroute in de app.', 'Wijzig je wachtwoord en zet tweestapsverificatie aan met een authenticator-app.', 'Verwijder de oplichtingsberichten, verhalen en livestreams.', 'Log onbekende sessies uit.', 'Waarschuw volgers via WhatsApp, e-mail of een ander account.'])),
  ('Melden', 'In Nederland kun je aangifte doen bij de politie en het melden bij de Fraudehelpdesk. In België meld je het bij de politie en via Safeonweb.')],
 [('Kan Instagram mijn account uitschakelen door de oplichting?', 'Ja, dat gebeurt soms. Vermeld de hack en de datum in je bezwaar.'),
  ('Volgers hebben geld overgemaakt. Wat nu?', 'Laat hen direct hun bank bellen en aangifte doen.'),
  ('Moet ik losgeld betalen aan de hacker?', 'Nee. Betalen levert zelden iets op.')], [('/nl/instagram-account-gehackt/', 'Instagram-account gehackt'), ('/nl/oplichting-account-herstel-waarschuwing/', 'Pas op voor nep-herstellers'), NR[0]])
page(N, 'meta-bedrijfsportfolio-uitgeschakeld', 'Meta-bedrijfsportfolio uitgeschakeld: alle advertenties weg',
 'Je Meta-bedrijfsportfolio is uitgeschakeld en alle advertentieaccounts en pagina’s erin liggen stil. Wat je controleert en hoe je om beoordeling vraagt.',
 'Je hele Meta-bedrijfsportfolio is uitgeschakeld?', 'Bedrijfsportfolio uitgeschakeld',
 'Als je Meta-bedrijfsportfolio is uitgeschakeld, stopt elk advertentieaccount erin, ook als dat zelf gezond leek. Open Business Support Home, kies het portfolio en lees de reden. Controleer of de profielen van de beheerders niet zelf beperkt zijn, rond verificatie af als dat wordt gevraagd en vraag als beheerder één keer om beoordeling.',
 [('Stappen', ol(['Open Business Support Home en kies het bedrijfsportfolio.', 'Lees de reden en wat je kunt doen.', 'Controleer elk beheerdersprofiel.', 'Rond bedrijfsverificatie af als dat wordt gevraagd.', 'Vraag om beoordeling en noteer de datum.'])),
  ('Wat je beter niet doet', 'Maak geen nieuw portfolio om de beperking te omzeilen. Dat kan de situatie erger maken.')],
 [('Kan ik advertentieaccounts verplaatsen?', 'Niet zolang het portfolio is uitgeschakeld.'),
  ('Zijn accounts van klanten ook geraakt?', 'Accounts in het eigen portfolio van een klant blijven vaak buiten schot. Laat klanten het vanaf hun kant controleren.'),
  ('Valt dit onder de DSA?', 'Advertentiebeperkingen vallen niet altijd onder elke geschilleninstantie.')], [('/nl/advertentieaccount-terugkrijgen/', 'Advertentieaccount terugkrijgen'), ('/nl/advertentieaccount-geen-beheerder-meer/', 'Geen beheerder meer'), ('/nl/advertentieaccount-bezwaar-wat-schrijven/', 'Wat schrijf je in een bezwaar')])
page(N, 'meta-bedrijfsverificatie-kvk-documenten', 'Meta-bedrijfsverificatie met KvK-uittreksel: welke documenten',
 'Welke documenten Meta accepteert voor bedrijfsverificatie in Nederland en België, waarom verificatie wordt afgewezen en hoe je het herstelt.',
 'Welke documenten accepteert Meta voor bedrijfsverificatie?', 'Bedrijfsverificatie',
 'Voor Meta-bedrijfsverificatie heb je een officieel document nodig met je juridische bedrijfsnaam, plus bewijs van adres of telefoonnummer. In Nederland is dat meestal een KvK-uittreksel, in België een uittreksel uit de KBO. De juridische naam moet exact overeenkomen met wat je invult, anders volgt vaak een afwijzing.',
 [('Waarom het wordt afgewezen', ul(['De naam wijkt af, bijvoorbeeld B.V. tegenover BV.', 'Het adres op het document verschilt van het ingevulde adres.', 'Het document is onscherp, bijgesneden of verlopen.', 'De website noemt het bedrijf niet.'])),
  ('Stappen', ol(['Open in Bedrijfsinstellingen het Beveiligingscentrum en start de verificatie.', 'Vul de juridische naam exact in zoals op het KvK-uittreksel.', 'Upload één duidelijk document en bevestig via e-mail, telefoon of domein.', 'Bij een afwijzing: lees de reden en herstel alleen dat.']))],
 [('Mag het KvK-uittreksel oud zijn?', 'Gebruik een recent uittreksel waarop de huidige gegevens staan.'),
  ('Kan een eenmanszaak verifiëren?', 'Ja, met een officieel document waarop de handelsnaam staat.'),
  ('Heft verificatie een advertentiebeperking op?', 'Soms is het de stap die Meta vraagt. Kijk wat Accountkwaliteit zegt.')], [('/nl/advertentieaccount-identiteitsverificatie-loopt-vast/', 'Verificatie loopt vast'), ('/nl/advertentieaccount-terugkrijgen/', 'Advertentieaccount terugkrijgen'), ('/nl/meta-bedrijfsportfolio-uitgeschakeld/', 'Bedrijfsportfolio uitgeschakeld')])
page(N, 'instagram-gebruikersnaam-claimen-met-merkregistratie', 'Instagram-gebruikersnaam claimen met een merkregistratie',
 'Hoe een merkregistratie bij het BOIP of EUIPO een claim op een Instagram-gebruikersnaam kan ondersteunen, en wanneer het niet helpt.',
 'Heb je een geregistreerd merk en heeft iemand anders de gebruikersnaam?', 'Gebruikersnaam en merk',
 'Een merkregistratie bij het BOIP of EUIPO kan een claim op een Instagram-gebruikersnaam ondersteunen als het account de naam gebruikt op een manier die inbreuk maakt op je merk, bijvoorbeeld door vergelijkbare producten te verkopen of je merk na te doen. Instagram kijkt naar de registratie, de klassen en hoe de naam wordt gebruikt.',
 [('Wat je klaarzet', ul(['Het registratienummer en het certificaat.', 'De klassen waarvoor het merk geldt.', 'Screenshots van het account en hoe het de naam gebruikt.', 'Bewijs dat je het merk gebruikt: website, producten, facturen.'])),
  ('Wanneer het minder helpt', ul(['Het account is inactief maar maakt geen inbreuk.', 'Het merk geldt voor andere klassen.', 'De naam is een gewoon woord.']))],
 [('Telt een aanvraag die nog loopt?', 'Een ingeschreven merk weegt veel zwaarder.'),
  ('Wat gebeurt er met de huidige houder?', 'Instagram beslist of de naam wordt overgedragen.'),
  ('Geldt er een terugbetalingsregeling?', 'Ja, voor gebruikersnaam-verzoeken. Vraag ernaar in het gesprek.')], [('/nl/instagram-gebruikersnaam-claimen/', 'Gebruikersnaam claimen'), ('/nl/instagram-gebruikersnaam-inactief-account/', 'Inactief account')])
page(N, 'avg-inzageverzoek-meta-uitgeschakeld-account', 'AVG-inzageverzoek bij Meta na een uitgeschakeld account',
 'Hoe je onder de AVG je persoonsgegevens bij Meta opvraagt na een Instagram- of Facebook-ban, wat je vraagt en wanneer je naar de AP stapt.',
 'Account uitgeschakeld? Je kunt Meta om je gegevens vragen.', 'AVG-inzageverzoek',
 'Onder de AVG mag je Meta vragen om een kopie van de persoonsgegevens die het over je bewaart, ook van een uitgeschakeld account. Meta moet normaal binnen een maand reageren, met verlenging mogelijk bij complexe verzoeken. Een inzageverzoek draait de ban niet terug, maar laat zien wat er is vastgelegd.',
 [('Zo doe je het verzoek', ol(['Gebruik het privacyformulier van Meta in het Privacycentrum of Helpcentrum.', 'Geef de gebruikersnaam, het e-mailadres of nummer en de datum van de uitschakeling.', 'Vraag om de persoonsgegevens, inclusief gegevens over de handhavingsbeslissing.', 'Bewaar een kopie en de verzenddatum.'])),
  ('Klacht indienen', 'Reageert Meta niet of onvolledig, meld dat eerst bij Meta. Daarna kun je een klacht indienen bij de Autoriteit Persoonsgegevens, in België bij de Gegevensbeschermingsautoriteit. Meta’s hoofdvestiging in de EU zit in Ierland, dus je klacht kan worden doorgestuurd. Dit is geen juridisch advies.')],
 [('Krijg ik zo mijn account terug?', 'Nee. Het gaat om je gegevens, niet om de ban.'),
  ('Kan ik ook vragen of de beslissing geautomatiseerd was?', 'Ja, dat kun je in hetzelfde verzoek vragen.'),
  ('Krijg ik mijn foto’s terug?', 'Vaak wel, als onderdeel van je persoonsgegevens.')], [NR[1], NR[0]])
page(N, 'gehackt-account-aangifte-doen', 'Gehackt Instagram- of Facebook-account: aangifte en melden',
 'Waar je een gehackt Instagram- of Facebook-account meldt in Nederland en België, en wanneer aangifte zinvol is.',
 'Waar meld je een gehackt account in Nederland of België?', 'Gehackt account melden',
 'Herstel eerst de toegang via de hackroute van Instagram of Facebook. Is er geld verloren, word je afgeperst of misbruikt iemand je identiteit, doe dan aangifte bij de politie. In Nederland meld je oplichting ook bij de Fraudehelpdesk, in België bij de politie en via Safeonweb. Melden herstelt het account niet, maar helpt je bank en verzekeraar.',
 [('Wat je meeneemt', ul(['De gebruikersnaam en de datum van de hack.', 'Screenshots van de berichten van de hacker.', 'Betalingen of overboekingen die zijn gedaan.'])),
  ('Afpersing', 'Word je afgeperst met beelden? Betaal niet, bewaar alles en neem contact op met de politie. Zie ook %s.' % A('/nl/sextortion-instagram-wat-te-doen/', 'sextortion: wat te doen'))],
 [('Kan de politie mijn account terughalen?', 'Nee, herstel gaat via het platform.'),
  ('Moet ik online of op het bureau aangifte doen?', 'Voor veel vormen van online oplichting kan het online. Volg wat de politie aangeeft.'),
  ('Helpt een aangifte bij mijn bezwaar?', 'Je kunt het noemen. Het platform beslist zelf.')], [('/nl/instagram-account-gehackt/', 'Instagram-account gehackt'), ('/nl/facebook-account-gehackt/', 'Facebook-account gehackt')])
F = 'fr'
FR = [('/fr/compte-instagram-desactive-comment-recuperer/', 'Compte Instagram désactivé'), ('/fr/droit-de-recours-dsa-meta/', 'Recours DSA (Europe)'), ('/fr/instagram-appel-refuse/', 'Appel Instagram refusé')]
page(F, 'compte-instagram-professionnel-desactive-revenus', 'Compte Instagram professionnel désactivé : protéger vos revenus',
 'Votre compte Instagram professionnel est désactivé et les ventes sont à l’arrêt. Quoi faire d’abord, comment faire appel et garder le contact avec vos clients.',
 'Compte Instagram professionnel désactivé, et c’est votre revenu ?', 'Compte pro désactivé',
 'Faites appel une seule fois depuis la notification, avec des informations exactes, avant la fin du délai. Ne créez pas de nouveau compte sur le même téléphone, car les comptes liés sont souvent supprimés aussi. Prévenez vos clients par e-mail, sur votre site ou votre fiche Google, et gardez chaque notification datée.',
 [('Les 48 premières heures', ol(['Faites une capture de la notification et du délai d’appel.', 'Faites appel depuis votre téléphone habituel et expliquez simplement ce que vend l’entreprise.', 'Faites la vérification d’identité ou le selfie vidéo une fois, avec une bonne lumière.', 'Vérifiez dans l’Espace comptes si votre profil Facebook est aussi restreint.', 'Mettez en pause les publicités liées au compte.'])),
  ('À éviter', ul(['Créer un nouveau compte avec le même e-mail, numéro ou appareil.', 'Payer quelqu’un en message privé qui dit connaître quelqu’un chez Meta.', 'Supprimer des publications en masse.']))],
 [('Mes abonnés sont-ils perdus ?', 'Le compte est masqué, pas supprimé. Si l’appel aboutit, abonnés et publications reviennent en général.'),
  ('Puis-je utiliser un nouveau compte en attendant ?', 'C’est risqué. Un compte lié à vous ou à l’appareil peut être supprimé pour la même raison.'),
  ('J’habite dans l’UE. Ai-je d’autres options ?', 'Oui. Après un appel refusé, vous pouvez saisir un organisme comme Appeals Centre Europe.')], FR)
page(F, 'compte-instagram-secours-aussi-suspendu', 'Compte Instagram de secours suspendu aussi : pourquoi',
 'Votre compte principal a été désactivé, puis votre compte de secours aussi. Pourquoi les comptes liés sont supprimés et ce qu’il vaut mieux faire.',
 'Votre compte Instagram de secours a aussi été suspendu ?', 'Compte de secours suspendu',
 'Instagram relie les comptes par l’appareil, le numéro, l’e-mail, les moyens de paiement et l’Espace comptes. Quand un compte est désactivé, un compte de secours ou nouveau qui lui est lié l’est souvent aussi, parfois pour contournement de la décision. Arrêtez de créer des comptes, faites appel pour le compte principal et gardez les preuves.',
 [('Que faire maintenant', ol(['Ne créez plus de comptes.', 'Faites appel pour le compte d’origine.', 'Gardez les captures des deux notifications avec leur date.'])),
  ('Pourquoi cela arrive', 'Meta cite le contournement des mesures comme motif pour supprimer aussi les comptes liés. Ce n’est pas ce que vous avez publié sur le compte de secours, c’est le lien entre les comptes.')],
 [('Puis-je faire appel pour le compte de secours ?', 'S’il y a un bouton, oui. Mais le compte principal est généralement la clé.'),
  ('Un autre téléphone peut-il aider ?', 'Utiliser un nouvel appareil pour contourner la décision va contre les règles.'),
  ('Le compte de secours revient-il avec le principal ?', 'Pas automatiquement, mais son appel a alors plus de chances.')], FR)
page(F, 'appeals-centre-europe-instagram-facebook', 'Appeals Centre Europe : contester une suspension Instagram',
 'Comment fonctionne Appeals Centre Europe pour un compte Instagram, Facebook ou TikTok suspendu : qui peut l’utiliser, le délai et ce qu’il faut attendre.',
 'Appeals Centre Europe peut-il examiner la suspension de votre compte ?', 'Appeals Centre Europe',
 'Appeals Centre Europe est un organisme de règlement extrajudiciaire certifié au titre du DSA. Il examine les suspensions de compte et les décisions de contenu de Facebook, Instagram, Threads, TikTok et YouTube notamment. Il faut résider dans l’UE, avoir 16 ans ou plus et saisir l’organisme dans les six mois suivant la décision. C’est gratuit pour les utilisateurs actuellement.',
 [('Comment saisir l’organisme', ol(['Terminez l’appel dans l’application et gardez la décision.', 'Allez sur appealscentre.eu et choisissez la plateforme.', 'Indiquez qu’il s’agit d’une suspension de compte.', 'Ajoutez le nom d’utilisateur, la date et la référence de la notification.', 'Expliquez brièvement pourquoi la décision est erronée. Le français est accepté.'])),
  ('À quoi s’attendre', 'La décision n’est pas contraignante, mais la plateforme doit participer de bonne foi. Selon ses propres rapports, l’organisme annule une partie des suspensions, pas toutes.')],
 [('Puis-je l’utiliser depuis la Suisse ?', 'Non, la Suisse n’est pas dans l’UE.'),
  ('Et depuis la Belgique ou le Luxembourg ?', 'Oui, ces pays sont dans l’UE.'),
  ('Unbanz peut-il le faire pour moi ?', 'Vous le déposez vous-même. Nous pouvons vous aider à mettre les faits en ordre.')], [FR[1], FR[2], ('/fr/instagram-compte-suspendu-180-jours/', 'Suspendu, 180 jours')])
page(F, 'meta-verified-assistance-compte-desactive', 'Meta Verified et compte désactivé : ce que fait l’assistance',
 'Ce que l’assistance Meta Verified peut faire, ou non, quand votre compte Instagram ou Facebook est désactivé ou piraté, et comment ouvrir le chat.',
 'L’assistance Meta Verified aide-t-elle pour un compte désactivé ?', 'Assistance Meta Verified',
 'Meta Verified donne accès à une assistance par chat ou e-mail, mais seulement depuis un compte actif abonné. Si le compte lui-même est désactivé, l’assistance renvoie souvent vers l’appel habituel. Un compte actif lié avec Meta Verified peut parfois aider en cas de piratage.',
 [('Ouvrir l’assistance', ol(['Ouvrez le compte abonné à Meta Verified.', 'Allez dans Espace comptes, Meta Verified, puis Contacter l’assistance.', 'Donnez le nom d’utilisateur du compte concerné et la date.'])),
  ('À quoi s’attendre', 'L’assistance peut expliquer, transmettre un signalement ou orienter vers le bon formulaire. Elle ne peut généralement pas annuler une désactivation elle-même.')],
 [('Faut-il s’abonner pour récupérer un compte ?', 'Pas si le compte est déjà désactivé. Faites d’abord appel.'),
  ('Puis-je résilier ?', 'Oui, depuis l’Espace comptes ou la boutique d’applications utilisée.'),
  ('Y a-t-il d’autres voies ?', 'Dans l’UE, après un appel refusé, Appeals Centre Europe.')], FR)
page(F, 'instagram-pirate-publications-crypto', 'Instagram piraté qui publie des arnaques crypto : que faire',
 'Votre compte Instagram piraté publie des arnaques aux cryptos ou à l’investissement. Comment le récupérer, prévenir vos abonnés et signaler.',
 'Votre Instagram piraté publie des arnaques crypto ?', 'Piraté, arnaques crypto',
 'Si votre compte Instagram piraté publie des arnaques crypto, récupérez d’abord l’accès via instagram.com/hacked ou l’e-mail de sécurité, puis supprimez les publications et stories. Prévenez vos abonnés par un autre canal. En France, signalez sur cybermalveillance.gouv.fr et portez plainte, en ligne ou au commissariat.',
 [('Étape par étape', ol(['Utilisez le lien de l’e-mail de sécurité officiel ou la procédure piratage de l’application.', 'Changez le mot de passe et activez la double authentification avec une application.', 'Supprimez les publications, stories et lives frauduleux.', 'Déconnectez les sessions inconnues.', 'Prévenez vos abonnés par e-mail, WhatsApp ou un autre compte.'])),
  ('Signaler', 'En France : cybermalveillance.gouv.fr pour l’assistance, et une plainte si de l’argent a été perdu. En Belgique : la police et Safeonweb. En Suisse : le portail de l’OFCS.')],
 [('Instagram peut-il désactiver mon compte à cause de l’arnaque ?', 'Oui, cela arrive. Mentionnez le piratage et la date dans votre appel.'),
  ('Des abonnés ont envoyé de l’argent. Que faire ?', 'Qu’ils contactent tout de suite leur banque et portent plainte.'),
  ('Dois-je payer le pirate ?', 'Non. Payer donne rarement quelque chose.')], [('/fr/compte-instagram-pirate-que-faire/', 'Compte Instagram piraté'), ('/fr/faux-hackers-arnaque-recuperation-compte/', 'Faux hackers'), FR[0]])
page(F, 'portefeuille-business-meta-desactive', 'Portefeuille business Meta désactivé : tous les comptes pub',
 'Votre portefeuille business Meta est désactivé et tous ses comptes publicitaires sont bloqués. Quoi vérifier et comment demander un examen.',
 'Tout votre portefeuille business Meta est désactivé ?', 'Portefeuille business désactivé',
 'Si votre portefeuille business Meta est désactivé, chaque compte publicitaire qu’il contient s’arrête, même s’il semblait sain. Ouvrez Business Support Home, choisissez le portefeuille et lisez le motif. Vérifiez que les profils des administrateurs ne sont pas eux-mêmes restreints, terminez la vérification si demandée, puis demandez un examen une fois.',
 [('Étapes', ol(['Ouvrez Business Support Home et sélectionnez le portefeuille.', 'Lisez le motif et les actions proposées.', 'Vérifiez chaque profil administrateur.', 'Terminez la vérification d’entreprise si elle est demandée.', 'Demandez un examen et notez la date.'])),
  ('À éviter', 'Ne créez pas de nouveau portefeuille pour contourner la restriction. Cela peut aggraver la situation.')],
 [('Puis-je déplacer les comptes publicitaires ?', 'Pas tant que le portefeuille est désactivé.'),
  ('Les comptes de mes clients sont-ils touchés ?', 'Les comptes dans le portefeuille propre du client restent souvent hors de cause. Demandez-leur de vérifier.'),
  ('Le DSA s’applique-t-il ?', 'Les restrictions publicitaires ne relèvent pas toujours de chaque organisme de règlement.')], [('/fr/business-manager-meta-restreint/', 'Business Manager restreint'), ('/fr/compte-publicitaire-perte-acces-administrateur/', 'Perte d’accès administrateur'), ('/fr/compte-publicitaire-meta-demande-de-reexamen-quoi-ecrire/', 'Demande de réexamen')])
page(F, 'verification-entreprise-meta-kbis', 'Vérification d’entreprise Meta avec un Kbis : documents',
 'Quels documents Meta accepte pour la vérification d’entreprise en France, Belgique et Suisse, pourquoi elle est refusée et comment corriger.',
 'Quels documents Meta accepte-t-il pour vérifier votre entreprise ?', 'Vérification d’entreprise',
 'La vérification d’entreprise Meta demande un document officiel avec la dénomination légale, et une preuve d’adresse ou de téléphone. En France, un extrait Kbis ou un avis de situation SIRENE convient souvent, en Belgique un extrait de la BCE, en Suisse un extrait du registre du commerce. La dénomination doit correspondre exactement.',
 [('Motifs de refus fréquents', ul(['La dénomination diffère, par exemple SAS ou non.', 'L’adresse du document diffère de celle saisie.', 'Le document est flou, recadré ou trop ancien.', 'Le site web ne mentionne pas l’entreprise.'])),
  ('Étapes', ol(['Dans les paramètres business, ouvrez le Centre de sécurité et lancez la vérification.', 'Saisissez la dénomination exacte du Kbis.', 'Envoyez un document net et confirmez par e-mail, téléphone ou domaine.', 'En cas de refus, lisez le motif et corrigez uniquement ce point.']))],
 [('Un auto-entrepreneur peut-il vérifier ?', 'Oui, avec un avis de situation SIRENE ou un document officiel équivalent.'),
  ('Le Kbis doit-il être récent ?', 'Utilisez un extrait récent qui montre les informations actuelles.'),
  ('La vérification lève-t-elle une restriction pub ?', 'Parfois, c’est l’étape demandée. Regardez la Qualité du compte.')], [('/fr/compte-publicitaire-verification-identite-boucle/', 'Vérification en boucle'), ('/fr/compte-publicitaire-meta-restreint/', 'Compte publicitaire restreint'), ('/fr/portefeuille-business-meta-desactive/', 'Portefeuille désactivé')])
page(F, 'pseudo-instagram-marque-deposee-inpi', 'Pseudo Instagram et marque déposée (INPI, EUIPO)',
 'Comment une marque déposée à l’INPI ou à l’EUIPO peut appuyer une demande de pseudo Instagram, et quand cela ne suffit pas.',
 'Vous avez une marque déposée et quelqu’un a votre pseudo Instagram ?', 'Pseudo et marque déposée',
 'Une marque enregistrée à l’INPI ou à l’EUIPO peut appuyer une demande de pseudo Instagram si le compte qui le détient l’utilise d’une manière qui porte atteinte à votre marque, par exemple en vendant des produits similaires ou en se faisant passer pour vous. Instagram regarde l’enregistrement, les classes et l’usage du nom.',
 [('À préparer', ul(['Le numéro d’enregistrement et le certificat.', 'Les classes couvertes.', 'Des captures du compte et de l’usage du nom.', 'La preuve que vous utilisez la marque : site, produits, factures.'])),
  ('Quand cela aide moins', ul(['Le compte est inactif mais ne porte pas atteinte à la marque.', 'La marque couvre d’autres classes.', 'Le nom est un mot courant.']))],
 [('Un dépôt en cours suffit-il ?', 'Une marque enregistrée pèse beaucoup plus.'),
  ('Que devient le titulaire actuel ?', 'Instagram décide de transférer ou non le pseudo.'),
  ('Y a-t-il une politique de remboursement ?', 'Oui, pour les demandes de pseudo. Demandez-nous les détails.')], [('/fr/pseudo-instagram/', 'Pseudo Instagram'), ('/fr/pseudo-instagram-deja-pris-compte-inactif/', 'Pseudo pris, compte inactif')])
page(F, 'rgpd-demande-acces-meta-compte-desactive', 'RGPD : demander vos données à Meta après une désactivation',
 'Comment demander à Meta une copie de vos données personnelles après la désactivation d’un compte Instagram ou Facebook, et quand saisir la CNIL.',
 'Compte désactivé ? Vous pouvez demander vos données à Meta.', 'Demande d’accès RGPD',
 'Le RGPD vous permet de demander à Meta une copie des données personnelles qu’il conserve, y compris pour un compte désactivé. Meta doit en principe répondre sous un mois, avec une prolongation possible pour les demandes complexes. La demande n’annule pas la désactivation, mais montre ce qui a été enregistré.',
 [('Faire la demande', ol(['Utilisez le formulaire de confidentialité de Meta dans l’Espace confidentialité ou l’Aide de Meta.', 'Indiquez le nom d’utilisateur, l’e-mail ou le numéro et la date de désactivation.', 'Demandez vos données, y compris celles liées à la décision.', 'Gardez une copie et la date d’envoi.'])),
  ('Réclamation', 'Sans réponse ou avec une réponse incomplète, relancez Meta. Ensuite vous pouvez saisir la CNIL en France, l’APD en Belgique ou le PFPDT en Suisse. L’établissement principal de Meta dans l’UE est en Irlande, la réclamation peut donc être transmise. Ce n’est pas un conseil juridique.')],
 [('Vais-je récupérer mon compte ainsi ?', 'Non. Il s’agit de vos données, pas de la décision.'),
  ('Puis-je demander si la décision était automatisée ?', 'Oui, dans la même demande.'),
  ('Vais-je récupérer mes photos ?', 'Souvent oui, au titre de vos données personnelles.')], [FR[1], FR[0]])
page(F, 'compte-pirate-porter-plainte-signaler', 'Compte Instagram ou Facebook piraté : où signaler',
 'Où signaler un compte Instagram ou Facebook piraté en France, Belgique et Suisse, et quand porter plainte.',
 'Où signaler un compte piraté en France, Belgique ou Suisse ?', 'Signaler un piratage',
 'Récupérez d’abord l’accès via la procédure piratage d’Instagram ou Facebook. Si de l’argent a été perdu, s’il y a chantage ou usurpation d’identité, portez plainte. En France, cybermalveillance.gouv.fr vous oriente et Pharos reçoit les signalements de contenus illicites. Le signalement ne rend pas le compte, mais aide votre banque et votre assureur.',
 [('À préparer', ul(['Le nom d’utilisateur et la date du piratage.', 'Les captures des messages du pirate.', 'Les paiements ou virements effectués.'])),
  ('Chantage', 'Si vous êtes victime de chantage avec des images, ne payez pas, gardez tout et contactez la police. Voir %s.' % A('/fr/sextorsion-instagram-que-faire/', 'sextorsion : que faire'))],
 [('La police peut-elle récupérer mon compte ?', 'Non, la récupération passe par la plateforme.'),
  ('Belgique et Suisse ?', 'En Belgique, la police et Safeonweb. En Suisse, la police et le portail de l’OFCS.'),
  ('La plainte aide-t-elle mon appel ?', 'Vous pouvez la mentionner. La plateforme décide.')], [('/fr/compte-instagram-pirate-que-faire/', 'Compte Instagram piraté'), ('/fr/compte-facebook-pirate-que-faire/', 'Compte Facebook piraté')])
